//go:build integration

// This integration test imports the actual official source-plugin installation
// generated by linactl build. Run it with that build's Go workspace. It freezes
// startup declarations only: no routes, jobs, database or supplier calls run.
package startupregistration_test

import (
	"testing"

	"lina-core/pkg/plugin/pluginhost"
	"lina-plugin-idc-core/backend/cap/customer360cap"
	customer360spi "lina-plugin-idc-core/backend/cap/customer360cap/spi"
	"lina-plugin-idc-core/backend/cap/customerclosurecap"
	closurespi "lina-plugin-idc-core/backend/cap/customerclosurecap/spi"
	_ "lina-plugins"
)

// TestOfficialPluginStartupCoverage catches gaps that local registrar stubs
// cannot detect, including a missing real owner or obsolete required count.
func TestOfficialPluginStartupCoverage(t *testing.T) {
	for _, pluginID := range []string{"idc-core", "idc-compliance", "idc-notify", "idc-resource"} {
		if _, ok := pluginhost.GetSourcePlugin(pluginID); !ok {
			t.Fatalf("required source plugin not registered: %s", pluginID)
		}
	}

	summaries, err := customer360spi.Freeze()
	if err != nil {
		t.Fatalf("freeze actual customer summary owners: %v", err)
	}
	summaryCounts := make(map[customer360cap.Code]int)
	for _, owner := range summaries {
		for _, code := range owner.Codes() {
			summaryCounts[code]++
		}
	}
	requiredSummaries := []customer360cap.Code{
		customer360cap.CodeOrders, customer360cap.CodeBills, customer360cap.CodeTransactions,
		customer360cap.CodeServers, customer360cap.CodeTaxInvoices, customer360cap.CodeTickets,
		customer360cap.CodeNotifications, customer360cap.CodeAudits,
	}
	if len(summaryCounts) != len(requiredSummaries) {
		t.Fatalf("unexpected actual summary declarations: %v", summaryCounts)
	}
	for _, code := range requiredSummaries {
		if summaryCounts[code] != 1 {
			t.Errorf("summary %s must have one actual owner, got %d", code, summaryCounts[code])
		}
	}

	closures, err := closurespi.Freeze()
	if err != nil {
		t.Fatalf("freeze actual account closure owners: %v", err)
	}
	closureCounts := make(map[customerclosurecap.Code]int)
	for _, owner := range closures {
		for _, code := range owner.Codes() {
			closureCounts[code]++
		}
	}
	requiredClosureFindings := []customerclosurecap.Code{
		customerclosurecap.CodeUnsettledFunds, customerclosurecap.CodeUnsettledInvoices,
		customerclosurecap.CodeActiveServices, customerclosurecap.CodeInProgressOperations,
		customerclosurecap.CodeLegalRetention,
	}
	if len(closureCounts) != len(requiredClosureFindings) {
		t.Fatalf("unexpected actual closure declarations: %v", closureCounts)
	}
	for _, code := range requiredClosureFindings {
		if closureCounts[code] != 1 {
			t.Errorf("closure finding %s must have one actual owner, got %d", code, closureCounts[code])
		}
	}
}
